            case TOWN_RAMPART:
            case TOWN_TOWER:
                goto evil_fog_good;
            case TOWN_INFERNO:
            case TOWN_NECROPOLIS:
            case TOWN_DUNGEON:
                goto evil_fog_evil;
            case TOWN_STRONGHOLD:
            case TOWN_FORTRESS:
            case TOWN_CONFLUX:
